static class Solution
    public static int CountOccurrences(string text, string pattern)
        if (len(pattern) == 0)
            return 0
        let mut count = 0
        let mut i = 0
        while i < len(text)
            if text[i] == first(pattern)
                let mut j = 0
                while j < len(pattern)
                    if text[i + j] != first(pattern + j)
                        break
                    j += 1
                if j == len(pattern)
                    count += 1
            i += 1
        return count

